// 1. Formatear Historial (De más viejo a más nuevo para que la IA entienda el hilo)
const historyItems = $('Read History').all();
let chatString = "";

// Invertimos el orden porque SQL trajo el más nuevo primero (DESC)
for (let i = historyItems.length - 1; i >= 0; i--) {
    const item = historyItems[i].json;
    const role = item.sender === 'client' ? 'Usuario' : 'Aura (Bot)';
    chatString += `${role}: ${item.content}\n`;
}

// 2. Formatear Pedido Activo
const orderData = $('Get Active Order').first().json;
let orderContext = "NO hay pedido activo. El cliente está explorando.";

// Si la query de orden no está vacía (tiene ID)
if (orderData && orderData.id) {
    orderContext = `PEDIDO ACTIVO ENCONTRADO:\n- ID: ${orderData.id}\n- Estado: ${orderData.status}\n- Producto: ${orderData.product_details}\n- Método Entrega: ${orderData.delivery_method || 'Por definir'}`;
}

return {
    json: {
        formatted_history: chatString,
        formatted_order: orderContext,
        client_message: $('Data Webhook').first().json.message
    }
};

